---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Form: A project brief with inline checks and an agent that drafts the rest.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change form.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './form.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="form" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<form class="fmx panel" novalidate>
  <div class="fmx-h"><b>New project brief</b><button type="button" class="pill soft sm fmx-ai"><svg class="i xs"><use href="#i-spark"/></svg>Draft with agent</button></div>
  <label class="fmx-f"><span>Project name<i class="fmx-dr" aria-hidden="true"><svg class="i xs"><use href="#i-spark"/></svg>Drafted</i></span><input name="n" placeholder="Pricing refresh" maxlength="40"><em class="fmx-c num">0/40</em></label>
  <label class="fmx-f"><span>Goal<i class="fmx-dr" aria-hidden="true"><svg class="i xs"><use href="#i-spark"/></svg>Drafted</i></span><textarea name="g" rows="2" placeholder="What should change, and why?"></textarea></label>
  <div class="fmx-f"><span>Type</span><div class="fmx-ty"><button type="button" class="chip sm" data-v="web">Website</button><button type="button" class="chip sm" data-v="app">App</button><button type="button" class="chip sm" data-v="brand">Brand</button></div></div>
  <label class="fmx-f"><span>Due<i class="fmx-dr" aria-hidden="true"><svg class="i xs"><use href="#i-spark"/></svg>Drafted</i></span><input name="d" type="text" placeholder="Nov 14"></label>
  <div class="fmx-ft"><span class="fmx-ms muted"></span><button class="pill primary sm fmx-go" type="submit">Create brief</button></div>
</form>
  </Fragment></div>
</div>
<script>
  import './form.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Form ---------- */
.fmx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3);max-width:380px;margin:0 auto;width:100%}
.fmx-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2)}
.fmx-h b{font-weight:500;font-size:14px}
.fmx-f{display:flex;flex-direction:column;gap:5px;font-size:12.5px;font-weight:500;position:relative}
.fmx-f input,.fmx-f textarea{border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);padding:10px var(--dm-s-3);font:inherit;font-size:13.5px;line-height:20px;font-weight:400;color:var(--dm-fg);resize:none;transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.fmx-f :is(input,textarea){corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.fmx-f input::placeholder,.fmx-f textarea::placeholder{color:var(--dm-muted)}
.fmx-f input:focus,.fmx-f textarea:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* a field marked wrong keeps its red edge, focused or not, until it is fixed; the message says what is wrong */
.fmx-f.bad input,.fmx-f.bad textarea{box-shadow:inset 0 0 0 1px var(--dm-bad)}
.fmx-f .er{font-size:11.5px;color:var(--dm-bad);font-weight:400;animation:enter .35s var(--dm-ease) backwards}
/* what the agent drafted says so quietly beside its label, until someone edits it */
.fmx-f>span:first-child{display:flex;align-items:center;gap:var(--dm-s-2)}
.fmx-dr{display:inline-flex;align-items:center;gap:3px;font-style:normal;font-size:11px;font-weight:400;color:var(--dm-muted);opacity:0;transform:translateX(-3px);transition:opacity var(--dm-t) var(--dm-ease),transform var(--dm-t) var(--dm-ease)}
.fmx-dr .i{color:var(--dm-accent-fg,var(--dm-accent))}
.fmx-f.ai .fmx-dr{opacity:1;transform:none}
.fmx-c{position:absolute;right:12px;top:24px;height:40px;display:flex;align-items:center;font-style:normal;font-size:11px;color:var(--dm-muted);font-weight:400;pointer-events:none}
.fmx-ty{display:flex;gap:6px}
/* the types are white chips with a dimmed grey edge; the picked one's edge is a step stronger */
.fmx-ty .chip{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent)}
@media (hover:hover) and (pointer:fine){.fmx-ty .chip:hover{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-faint) 50%,transparent)}}
.fmx-ft{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);margin-top:var(--dm-s-1)}
.fmx-ms{font-size:12px}
.fmx-done{display:flex;flex-direction:column;align-items:center;gap:6px;padding:var(--dm-s-6) 0;text-align:center;font-size:13px}
.fmx-done>svg{width:28px;height:28px;color:var(--dm-ok)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, hold, html, stagger, swap } from '../core/core.js';
DM.def('form', (r, c) => {
  r.innerHTML = r.innerHTML.split('{spark}').join(I('spark','xs'));
  const form = $('.fmx', r), n = $('[name=n]', r), g = $('[name=g]', r), d = $('[name=d]', r), cnt = $('.fmx-c', r), ms = $('.fmx-ms', r);
  let type = null;
  n.oninput = () => { cnt.textContent = n.value.length + '/40'; clear(n); };
  g.oninput = () => clear(g); d.oninput = () => clear(d);
  const chips = $$('.fmx-ty .chip', r);
  chips.forEach(ch => ch.onclick = () => { type = ch.dataset.v; chips.forEach(x => x.classList.toggle('on', x === ch)); clear(ch.parentElement); });
  function clear(el){ const f = el.closest('.fmx-f'); f.classList.remove('bad', 'ai'); $('.er', f)?.remove(); }
  function bad(el, t){ const f = el.closest('.fmx-f'); if (f.classList.contains('bad')) return; f.classList.add('bad'); f.insertAdjacentHTML('beforeend', `<span class="er">${t}</span>`); }
  async function type_(el, s){ el.closest('.fmx-f').classList.add('ai'); el.value = ''; for (const ch of s){ el.value += ch; el.dispatchEvent(new Event('input')); el.closest('.fmx-f').classList.add('ai'); await c.wait(18); } }
  $('.fmx-ai', r).onclick = () => c.run(async () => {
    const b = $('.fmx-ai', r); b.innerHTML = '<span class="think on"><i></i><i></i><i></i><i></i></span>Drafting';
    if (!n.value) await type_(n, 'Pricing refresh');
    await type_(g, 'Lift trial to paid by showing annual plans first and keeping one CTA per card.');
    if (!type) chips[0].click();
    if (!d.value) await type_(d, 'Nov 14');
    b.innerHTML = I('check','xs') + 'Drafted'; swap(ms, 'Review what the agent drafted');
  });
  // the preview has the agent fill it in once on its own, unless you take over first
  c.auto(1400, () => { if (!n.value) $('.fmx-ai', r).click(); });
  form.onsubmit = e => { e.preventDefault(); let ok = true;
    if (!n.value.trim()){ bad(n, 'Give it a name'); ok = false; }
    if (g.value.trim().length < 12){ bad(g, 'Add a sentence about the goal'); ok = false; }
    if (!type){ bad(chips[0], 'Pick a type'); ok = false; }
    if (!ok) return swap(ms, 'A few fields need a look');
    c.run(async () => { const go = $('.fmx-go', r); go.innerHTML = '<span class="spin"></span>'; await c.wait(800);
      hold(form); [...form.children].forEach(k => k.hidden = true); const dn = html(`<div class="fmx-done">${I('ok')}<b>${n.value} created</b><span class="muted">The agent is gathering references now</span></div>`); form.appendChild(dn); stagger([...dn.children], 70); }); };
});
